const LON0 = 14.0;
const LAT1 = 43.6;
const SCALE = 40.0;
const COS = Math.cos((25 * Math.PI) / 180);

/** Longitude/latitude to base-map units. */
export const projectNearEast = (lon: number, lat: number): [number, number] => [
  (lon - LON0) * COS * SCALE,
  (LAT1 - lat) * SCALE,
];

/** Base-map units back to longitude/latitude (for taps on the map). */
export const unprojectNearEast = (x: number, y: number): [number, number] => [
  LON0 + x / (COS * SCALE),
  LAT1 - y / SCALE,
];

/** Base-map units for one kilometre (north-south), for the scale bar. */
export const NEAR_EAST_UNITS_PER_KM = SCALE / 111.2;
